package com.example.yuejie;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.os.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public final class ShelfChecks extends DeviceChecks {
 public void shot(String name)throws Exception{waitForIdleSync();final android.graphics.Bitmap[] image={null};ui(()->{View decor=main.getWindow().getDecorView();image[0]=android.graphics.Bitmap.createBitmap(decor.getWidth(),decor.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);decor.draw(new android.graphics.Canvas(image[0]));});try(OutputStream out=new FileOutputStream(new File(output,name+".png"))){image[0].compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image[0].recycle();}
 JSONArray dir(int count)throws Exception{JSONArray a=new JSONArray();for(int i=0;i<count;i++)a.put(new JSONObject().put("id",Integer.toString(100+i)).put("title","第"+(i+1)+"章"));return a;}
 String positions(LocalLibrary db)throws Exception{JSONArray out=new JSONArray();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT book,chapter,offset,chapter_index,total,title,updated FROM progress ORDER BY book",null)){while(c.moveToNext()){JSONArray row=new JSONArray();for(int i=0;i<c.getColumnCount();i++)row.put(c.getString(i));out.put(row);}}return out.toString();}
 String order(LocalLibrary db)throws Exception{JSONArray out=new JSONArray();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,added,last_read FROM books ORDER BY id",null)){while(c.moveToNext())out.put(new JSONArray().put(c.getString(0)).put(c.getLong(1)).put(c.getLong(2)));}return out.toString();}
 void isolated()throws Exception{
  Context context=new TestContext(getTargetContext());SQLiteDatabase.deleteDatabase(context.getDatabasePath("reading-dog.db"));context.getSharedPreferences("reading_dog",0).edit().clear().putBoolean("sqlite_migrated",true).commit();LocalLibrary db=new LocalLibrary(context);Book b=new Book(new JSONObject().put("book_id","900").put("book_name","更新测试").put("author","旧作者"));db.add(b);db.directory(b.id,dir(3));db.progress(b.id,"101",99,1,3,"第二章");String before=positions(db),sort=order(db);db.directory(b.id,dir(5));assertTrue(db.catalogStatus(b,db.progress(b.id)).newChapters==2,"only appended chapters marked");assertTrue(before.equals(positions(db))&&sort.equals(order(db)),"refresh never writes reading location or order");LocalLibrary.CatalogStatus info=db.catalogStatus(b,db.progress(b.id));assertTrue(info.total==5&&info.current==2,"latest total with same current ID");db.close();db=new LocalLibrary(context);assertTrue(db.catalogStatus(b,db.progress(b.id)).newChapters==2,"marker persists restart");db.progress(b.id,"104",13,4,5,"第五章");assertTrue(db.catalogStatus(b,db.progress(b.id)).newChapters==0,"read new chapters clears marker");db.progress(b.id,"100",0,0,5,"第一章");assertTrue(db.catalogStatus(b,db.progress(b.id)).newChapters==0,"going backward does not revive old update badge");record("update_marker_count_acknowledge_restart",true);
  LocalLibrary isolated=db;CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1),done=new CountDownLatch(1);AtomicInteger calls=new AtomicInteger();ShelfRefresher service=new ShelfRefresher(db,book->{calls.incrementAndGet();entered.countDown();release.await(5,TimeUnit.SECONDS);isolated.directory(book.id,dir(6));});ShelfRefresher.Listener listener=new ShelfRefresher.Listener(){public void changed(){}public void complete(int ok,int failed){assertTrue(ok==1&&failed==0,"success summary");done.countDown();}};assertTrue(!service.refresh(false,listener),"fresh catalog TTL skips automatic network");assertTrue(service.refresh(true,listener),"manual ignores TTL");assertTrue(entered.await(5,TimeUnit.SECONDS),"worker started");assertTrue(!service.refresh(true,listener),"repeated pull merges in-flight work");release.countDown();assertTrue(done.await(5,TimeUnit.SECONDS),"refresh completes");assertTrue(calls.get()==1,"one request per book");service.close();record("automatic_ttl_force_and_dedup",true);
  db.add(new Book(new JSONObject().put("book_id","901").put("book_name","失败测试")));CountDownLatch partial=new CountDownLatch(1);String saved=positions(db);ShelfRefresher failures=new ShelfRefresher(db,book->{if(book.id.equals("901"))throw new IOException("controlled offline");isolated.directory(book.id,dir(7));});failures.refresh(true,new ShelfRefresher.Listener(){public void changed(){}public void complete(int ok,int failed){assertTrue(ok==1&&failed==1,"partial failure isolated");partial.countDown();}});assertTrue(partial.await(5,TimeUnit.SECONDS),"partial completion");assertTrue(saved.equals(positions(db)),"failure preserves read data");failures.close();record("partial_failure_and_read_position_preserved",true);
  db.close();
 }
 void live()throws Exception{
  LocalLibrary db=new LocalLibrary(getTargetContext());String before=positions(db),sort=order(db);launchMain();assertHome();waitFor(()->!main.shelfRefreshing,90,"automatic shelf check");assertTrue(before.equals(positions(db))&&sort.equals(order(db)),"automatic live refresh preserves exact progress and order");record("live_automatic_refresh",main.library.books(true).size());shot("home-after-automatic");
  ui(()->{main.scroll.scrollTo(0,0);});long checkedBefore=main.library.checkedAt(main.library.books(true).get(0).id);String firstBook=main.library.books(true).get(0).id;SystemClock.sleep(10);int w=main.scroll.getWidth();int[] origin=new int[2];ui(()->main.scroll.getLocationOnScreen(origin));ui(()->{long now=SystemClock.uptimeMillis();for(int i=0;i<=20;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==20?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;MotionEvent event=MotionEvent.obtain(now,now+i*25,action,w*.5f,50+340*i/20f,0);main.scroll.dispatchTouchEvent(event);event.recycle();}});waitFor(()->!main.shelfRefreshing&&main.library.checkedAt(firstBook)>checkedBefore,90,"pull refresh performs new network check");assertTrue(before.equals(positions(db))&&sort.equals(order(db)),"pull preserves exact position");record("native_view_pull_refresh_forces_live_network",true);shot("home-after-pull");
  JSONArray evidence=new JSONArray();for(Book b:db.books(true)){JSONObject p=db.progress(b.id);LocalLibrary.CatalogStatus status=db.catalogStatus(b,p);assertTrue(db.checkedAt(b.id)>0,"book checked "+b.title);assertTrue(status.total==db.directory(b.id).length(),"total from refreshed full catalog");evidence.put(new JSONObject().put("book",b.title).put("author",b.author).put("current",status.current).put("latest_total",status.total).put("new_chapters",status.newChapters).put("latest_title",status.latestTitle));}record("real_catalog_totals",evidence);
  // Deterministic UI update state in an isolated DB, without changing user data.
  LocalLibrary original=main.library;Context context=new TestContext(getTargetContext());LocalLibrary fixture=new LocalLibrary(context);ui(()->{main.shelfRefresher.close();main.library=fixture;main.render();});assertTrue(findText(main.getWindow().getDecorView(),"有新章 · 2")!=null,"shelf and recent badge visible");shot("home-new-chapters-fixture");
  ui(()->{main.shelfRefresher=new ShelfRefresher(fixture,book->{throw new IOException("controlled offline");});main.refreshShelf(true);});waitFor(()->!main.shelfRefreshing&&!main.shelfRefreshMessage.isEmpty(),8,"failed refresh UI");assertTrue(main.shelfRefreshMessage.contains("未能更新")&&findText(main.getWindow().getDecorView(),"更新测试")!=null,"failed refresh retains shelf with retry");shot("home-refresh-error-fixture");record("refresh_error_retains_home_retry",true);
  ui(()->{main.shelfRefresher.close();main.shelfRefresher=new ShelfRefresher(fixture,book->fixture.directory(book.id,dir(7)));main.refreshStatus.performClick();});waitFor(()->!main.shelfRefreshing&&main.shelfRefreshMessage.startsWith("已更新"),8,"retry UI succeeds");record("manual_retry_recovers",true);
  Book searchFixture=new Book(new JSONObject().put("book_id","900").put("book_name","搜索保留测试"));java.util.concurrent.CountDownLatch gate=new java.util.concurrent.CountDownLatch(1);ui(()->{main.shelfRefresher.close();main.shelfRefresher=new ShelfRefresher(fixture,book->gate.await(5,TimeUnit.SECONDS));main.refreshShelf(true);main.searching=true;main.query="fixture";main.results.clear();main.results.add(searchFixture);main.render();});gate.countDown();waitFor(()->!main.shelfRefreshing,8,"refresh completes while search active");assertTrue(findText(main.getWindow().getDecorView(),"搜索结果")!=null&&findText(main.getWindow().getDecorView(),"搜索保留测试")!=null,"late refresh does not replace search");record("search_and_shelf_refresh_independent",true);
  ui(()->{main.shelfRefresher.close();main.library=original;main.searching=false;main.results.clear();main.render();});fixture.close();assertHome();
 }
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"shelf-refresh-evidence");output.mkdirs();Bundle result=new Bundle();Throwable failure=null;try{isolated();live();}catch(Throwable e){failure=e;try{record("failure",android.util.Log.getStackTraceString(e));shot("failure");}catch(Exception ignored){}}try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,"results.json")),"UTF-8")){w.write(new JSONObject().put("success",failure==null).put("checks",checks).toString(2));}catch(Exception e){failure=e;}result.putString("stream",failure==null?"PASS "+checks.length()+" checks":"FAIL "+android.util.Log.getStackTraceString(failure));finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
